<?php
declare(strict_types=1);if(PHP_SAPI!=='cli'){http_response_code(403);exit;}require dirname(__DIR__).'/app/bootstrap.php';
try{$config=portal_config();$db=portal_open_database($config);$documents=$db->query("SELECT document_id,CONVERT(varchar(36),public_id) public_id,relative_path,file_name,extension,file_size_bytes,source_modified_at,content_hash,status_code FROM dbo.documents WHERE EXISTS(SELECT 1 FROM dbo.document_versions v WHERE v.document_id=documents.document_id)")->fetchAll();$streamDb=portal_open_sqlsrv_stream_database($config);$summary=['missing'=>0,'captured'=>0,'already_ready'=>0,'failed'=>0,'errors'=>[]];try{foreach($documents as $document){$vc=portal_document_version_config_for_document($config,$document);foreach(portal_get_database_document_versions($db,$document) as $version){if($version['has_content']){$summary['already_ready']++;continue;}$summary['missing']++;$manifest=portal_read_document_version_manifest($vc,$document,(string)$version['content_hash']);if(!is_array($manifest)){throw new RuntimeException('ARCHIVE_MANIFEST_UNAVAILABLE');}$path=(string)$manifest['artifact_path'];$stream=fopen($path,'rb');if(!is_resource($stream)||!flock($stream,LOCK_SH))throw new RuntimeException('ARCHIVE_LOCK_FAILED');try{$stat=fstat($stream);$ctx=hash_init('sha256');hash_update_stream($ctx,$stream);$hash=hash_final($ctx);if(!is_array($stat)||(int)$stat['size']!==(int)$version['file_size_bytes']||!hash_equals((string)$version['content_hash'],$hash)||!rewind($stream))throw new RuntimeException('ARCHIVE_INTEGRITY_FAILED');$versionId=(int)$version['version_id'];$params=[[&$versionId,SQLSRV_PARAM_IN,SQLSRV_PHPTYPE_INT,SQLSRV_SQLTYPE_BIGINT],[&$stream,SQLSRV_PARAM_IN,SQLSRV_PHPTYPE_STREAM(SQLSRV_ENC_BINARY),SQLSRV_SQLTYPE_VARBINARY('max')]];$stmt=sqlsrv_prepare($streamDb,'EXEC dbo.portal_backfill_document_version_content @version_id=?,@content_bytes=?',$params,['SendStreamParamsAtExec'=>false,'QueryTimeout'=>600]);if($stmt===false||!sqlsrv_execute($stmt))throw new RuntimeException('HISTORICAL_CAPTURE_START_FAILED');while(sqlsrv_send_stream_data($stmt)){}if(sqlsrv_fetch($stmt)!==true||(int)sqlsrv_get_field($stmt,0)!==$versionId||!hash_equals($hash,(string)sqlsrv_get_field($stmt,1)))throw new RuntimeException('HISTORICAL_CAPTURE_RESULT_FAILED');sqlsrv_free_stmt($stmt);$summary['captured']++;}finally{flock($stream,LOCK_UN);fclose($stream);}}}}finally{sqlsrv_close($streamDb);}echo json_encode($summary,JSON_UNESCAPED_SLASHES),PHP_EOL;exit($summary['failed']===0?0:2);}catch(Throwable $e){fwrite(STDERR,'Historical version backfill failed: '.$e->getMessage().PHP_EOL);exit(1);}
